    {
      "id": "structural_tam_gt_sam_gt_som",
      "category": "Structural Checks",
      "label": "TAM > SAM > SOM",
      "status": "pass",
      "notes": "Both approaches satisfy the hierarchy. Top-down: TAM $874M > SAM $402M > SOM $8M. Bottom-up: TAM $875M > SAM $804M > SOM $16M."
    },
    {
      "id": "structural_definitions_correct",
      "category": "Structural Checks",
      "label": "Definitions used correctly",
      "status": "pass",
      "notes": "TAM is the total US trade contractor FSM software market. SAM narrows to the SMB segment Cadence can actually serve (1\u201349 employees). SOM is the realistic 3-year capture at seed stage. Each layer is defined correctly and applied consistently across both approaches."
    },
    {
      "id": "tam_matches_product_scope",
      "category": "TAM Scoping",
      "label": "TAM matches product scope",
      "status": "pass",
      "notes": "The product targets HVAC, plumbing, and electrical contractors in the US SMB segment. The top-down TAM is explicitly scoped to US FSM software revenue attributable to those three trades. The bottom-up TAM uses US Census employer establishment counts for NAICS 238210 and 238220, which match the target trades precisely."
    },
    {
      "id": "source_segments_match",
      "category": "TAM Scoping",
      "label": "Source segments match product segments",
      "status": "pass",
      "notes": "The two primary market size sources (Market Research Future and PS Market Research) report on the US FSM market broadly, not specifically trade contractors. The analysis explicitly acknowledges this and derives the trade contractor slice using a separate estimate. Census data for NAICS 238210 and 238220 matches the target segment exactly. The mismatch in the top-level market sources is noted and handled through derivation rather than treated as a direct input."
    },
    {
      "id": "som_share_defensible",
      "category": "SOM Realism",
      "label": "SOM share is defensible",
      "status": "pass",
      "notes": "SOM is 2% of SAM over a 36-month window at seed stage, well below the 5% threshold that typically draws investor scrutiny in a fragmented market. The 2% figure is explicitly flagged as an agent estimate with low confidence, so the report signals uncertainty rather than asserting precision."
    },
    {
      "id": "som_backed_by_gtm",
      "category": "SOM Realism",
      "label": "SOM backed by go-to-market plan",
      "status": "fail",
      "notes": "No go-to-market plan was described in the materials provided. The 2% SAM capture rate is not connected to specific customer acquisition channels, funnel metrics, or analogous company benchmarks. Investors will ask how Cadence intends to reach contractors, and the sizing currently offers no answer."
    },
    {
      "id": "som_consistent_with_projections",
      "category": "SOM Realism",
      "label": "SOM consistent with financial projections",
      "status": "fail",
      "notes": "No financial projections, hiring plan, or burn rate were provided to cross-check against the SOM figure. The analysis cannot confirm whether the implied revenue ($8M\u2013$16M depending on approach) is consistent with Cadence's operational capacity over the 36-month window."
    },
    {
      "id": "data_current",
      "category": "Data Quality",
      "label": "Data is current",
      "status": "pass",
      "notes": "The US FSM market figures are from 2024 analyst reports. US Census County Business Patterns data is from 2023. ServiceTitan revenue and customer data is from fiscal year 2025 (reported January 2025). All key data points are within two years."
    },
    {
      "id": "sources_reputable",
      "category": "Data Quality",
      "label": "Sources are reputable",
      "status": "pass",
      "notes": "Primary sources include Market Research Future, PS Market Research, IBISWorld (analyst firms), US Census Bureau (government), and ServiceTitan's earnings release (company filing). Software Advice / Gartner is used for ARPU benchmarks. One source (Kore Komfort Solutions) is an industry blog and is used only for small-contractor ARPU comparison \u2014 not for market size baselines. Reputable sources carry the core inputs."
    },
    {
      "id": "figures_triangulated",
      "category": "Data Quality",
      "label": "Key figures triangulated",
      "status": "pass",
      "notes": "The US FSM market size is triangulated across three independent analyst estimates ($1.6B, $1.75B, $2.1B) and the mid-point is used. Establishment counts are cross-referenced between US Census CBP and IBISWorld. ARPU is built from two pricing references (Jobber and Housecall Pro data) plus a Software Advice / Gartner per-user spend figure for mid-sized contractors."
    },
    {
      "id": "unsupported_figures_flagged",
      "category": "Data Quality",
      "label": "Unsupported figures flagged",
      "status": "pass",
      "notes": "The 2% SOM capture rate is explicitly marked as an agent estimate with low confidence and the analysis notes no comparable seed-stage FSM SaaS ramp data was found. The SMB share of trade contractor FSM revenue is marked as a derived estimate with low confidence. The figure validation records for SAM and SOM are both labeled 'partially supported' and 'unsupported' respectively."
    },
    {
      "id": "validated_used_precisely",
      "category": "Data Quality",
      "label": "Validated used precisely",
      "status": "pass",
      "notes": "The analysis uses 'partially supported' (one source) and 'unsupported' (zero external sources) rather than claiming full validation. No figure is labeled 'validated' that does not meet the two-independent-source bar. The figure validation records for TAM, SAM, and SOM correctly reflect their evidentiary status."
