{
  "findings": [
    {
      "claim_attacked": "Bottom-up SAM uses the all-sizes blended ARPU of $4,500 after filtering customers to the SMB segment",
      "what_is_true": "The SAM build filters the total establishment count to SMB businesses (applying the 91.8% fraction to get 178,596 SMB customers) but then multiplies by $4,500 \u2014 the ARPU the analysis explicitly labels 'blended annual ARPU across ALL trade contractors (1\u2013500+ employees).' The analysis separately derives a 'blended annual ARPU for SMB trade contractors (1\u201349 employees)' of $2,340. Applying that SMB ARPU to the SMB customer count gives a bottom-up SAM of approximately $418M, which is closely aligned with the top-down SAM of $402M. The 2x discrepancy between the two SAM estimates that the analysis itself flags is therefore an artifact of this ARPU mismatch \u2014 not a genuine divergence between two independent market estimates.",
      "evidence_quote": "arpu_all_sizes_blended: Blended annual ARPU across ALL trade contractors (1\u2013500+ employees) \u2014 used for bottom-up TAM",
      "source_url": "internal:analysis",
      "source_title": "Analysis \u2014 the sizing calculation / the source validation",
      "severity": "high",
      "quote_verified": null,
      "parameter": "arpu"
    },
    {
      "claim_attacked": "The US FSM software market mid-point is stated as $1.9B, described as the mid-point of three analyst estimates ($1.6B, $1.75B, $2.1B)",
      "what_is_true": "The mean of the three figures the analysis lists ($1.6B, $1.75B, $2.1B) is $5.45B \u00f7 3 = $1.817B. The midpoint of the low-to-high range ($1.6B to $2.1B) is ($1.6B + $2.1B) \u00f7 2 = $1.85B. Neither calculation produces $1.9B. The $1.9B figure used as the market base is approximately 4\u20135% above either defensible averaging method, overstating the starting total and all top-down figures that flow from it.",
      "evidence_quote": "US field service management software market, 2024 (mid-point of three analyst estimates: $1.6B, $1.75B, $2.1B)",
      "source_url": "internal:analysis",
      "source_title": "Analysis \u2014 the source validation assumption us fsm software market 2024",
      "severity": "low",
      "quote_verified": null,
      "parameter": "industry_total"
    },
    {
      "claim_attacked": "The $1.6B low FSM market estimate is attributed to 'ResearchAndMarkets 2025 US Field Service Management Report'",
      "what_is_true": "The source URL recorded for this estimate points to https://www.marketresearchfuture.com/reports/us-field-service-management-market-15465, which is a Market Research Future report, not a ResearchAndMarkets report. These are two different firms with different coverage. Market Research Future's own published figure for the 2024 US FSM market is $1.75\u20131.8B, not $1.6B. The $1.6B figure does not appear to match the source URL it is paired with. The same Market Research Future URL is also cited for the overall $1.9B mid-point, meaning both the mid-point and the low estimate share one URL that cannot support both values.",
      "evidence_quote": "us_fsm_market_low \u2026 source_title: 'ResearchAndMarkets 2025 US Field Service Management Report' \u2026 source_url: 'https://www.marketresearchfuture.com/reports/us-field-service-management-market-15465'",
      "source_url": "internal:analysis",
      "source_title": "Analysis \u2014 the source validation assumption us fsm market low",
      "severity": "medium",
      "quote_verified": null,
      "parameter": "industry_total"
    },
    {
      "claim_attacked": "Large contractor ARPU used in the bottom-up TAM build is $20,000 per year",
      "what_is_true": "The analysis derives ServiceTitan's implied annual revenue per customer as $81,253 (FY2025 revenue $771.9M \u00f7 9,500 active customers). ServiceTitan serves primarily mid-to-large trade contractors. The analysis's $20,000 figure for the large-contractor (50+ employees) ARPU tier is approximately 4\u00d7 lower than the implied ARPU of the market's dominant platform in that segment. Even if some of ServiceTitan's customers are smaller than the typical 'large contractor,' the gap is large enough to suggest the bottom-up TAM materially underestimates the large-contractor revenue contribution.",
      "evidence_quote": "servicetitan_arpu_implied: ServiceTitan implied annual revenue per customer (FY2025 revenue \u00f7 active customers) \u2026 arpu: $81,253",
